export type ActorRole = 'gatherer' | 'guard' | 'scout';
export type ModuleConfig = {
  gather: { targetRoomId?: string };
  haul: { minCargo: number };
  build: { roomId: string; buildingKind: 'tower' | 'catalog'; minMaterials: number };
  defend: { roomId?: string };
  retreat: { hpThreshold: number };
};
export type BehaviorModule = { [K in keyof ModuleConfig]: {
  moduleId: string; kind: K; enabled: boolean; priority: number;
  roleFilter?: ActorRole[]; config: ModuleConfig[K];
} }[keyof ModuleConfig];
export interface BehaviorPlan {
  schemaVersion: 1;
  compositionId: string;
  mode: 'priority';
  modules: BehaviorModule[];
  fallbackModuleId: 'hold';
}

export type RoomRef = { type: 'room'; roomId: string };
export type OwnRoleRef = { type: 'ownRole'; role: ActorRole };
export type ModuleRef = RoomRef | OwnRoleRef;
export type CompositionConfig = {
  scout: { target: RoomRef; maxEnemyHp: number; reportIntervalTicks: number };
  patrol: { rooms: RoomRef[]; dwellTicks: number };
  escort: { target: OwnRoleRef; minCargo: number };
};
export type CompositionModule = { [K in keyof CompositionConfig]: {
  moduleId: string; kind: K; enabled: boolean; priority: number;
  roleFilter?: ActorRole[]; config: CompositionConfig[K];
} }[keyof CompositionConfig];
export type GraphModule = BehaviorModule | CompositionModule;
export type ModuleReasonCode = 'official-selected' | 'official-unavailable' | 'disabled' | 'role-filtered' | 'room-missing' | 'risk-exceeded' | 'travel-active' | 'route-unavailable' | 'moving' | 'scout-reported' | 'scout-report-cooldown' | 'patrol-dwelling' | 'patrol-advanced' | 'escort-target-missing' | 'escort-cargo-insufficient' | 'escort-safe' | 'escort-defending';
export interface ModuleVisit {
  nodeId: string; moduleId: string; outcome: 'selected' | 'fallback' | 'hold';
  reasonCode: ModuleReasonCode; ref?: ModuleRef; resolvedId?: string;
  observed?: { tick?: number; enemyHp?: number; threshold?: number; cargo?: number; cursor?: number; arrivedTick?: number };
  fallbackNodeId?: string;
}
export type GraphField = 'hp' | 'cargo' | 'cargoCapacity' | 'materials' | 'roomEnemyHp' | 'targetEnemyHp' | 'tickInState';
export type GraphCondition =
  | { type: 'compare'; field: GraphField; op: 'lt' | 'lte' | 'eq' | 'gte' | 'gt'; value: number; missing: boolean; roomId?: string }
  | { type: 'atRoom'; roomId: string; missing: boolean }
